{
  "case_id": "xsu_sg_004_multiple_impairments",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret rummer en væsentlig fejl: Det siger, at UDK \"kun\" vurderer de selvangivne funktionsnedsættelser, og det gør ansvaret til \"ansøgerens ansvar\" uden forbehold. Det udelader den samlede vurdering af flere ansøgte og dokumenterede funktionsnedsættelser. Det udelader også, at ansøgeren skal dokumentere dem og oplyse, at der søges på flere. Den senere tilføjelse er heller ikke betinget af varighed og minimumskrav til dokumentation. Det modsvarer rubrikkens materielle fejl om en senere tilføjelse uden krav om varighed og dokumentation."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "To kritiske elementer mangler: (1) at flere ansøgte og dokumenterede funktionsnedsættelser vurderes samlet, og (2) at ansøgeren skal dokumentere de angivne funktionsnedsættelser. Svaret nævner heller ikke, at minimumskravene til dokumentation skal være opfyldt for den senere tilføjede funktionsnedsættelse. Udgangspunktet om kun angivne funktionsnedsættelser og muligheden for senere inddragelse er med."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvilke funktionsnedsættelser UDK vurderer, når der er flere, og indeholder ikke irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som bestemmelse, afsnit eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en absolut regel: UDK vurderer \"kun\" de selvangivne funktionsnedsættelser, og \"Det er altså ansøgerens ansvar\". Kilden siger \"som udgangspunkt alene\", og svaret mangler også kravet om varighed og dokumentation. Det er ikke dækket af materialet."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Forbeholdet \"som udgangspunkt\" er udeladt. Journalomtale alene er ikke tilstrækkelig, men det er ikke udtrykt. Betingelsen om, at den senere funktionsnedsættelse skal være varig og opfylde minimumskravene til dokumentation, er ikke bevaret. Svaret nævner kun \"varig\" og \"fyldestgørende dokumentation\"."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: Hovedreglen om det angivne, undtagelsen via tilføjelse under sagsbehandlingen og konklusionen om ansøgerens ansvar hænger sammen."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør et udgangspunkt absolut med \"kun\" i stedet for \"som udgangspunkt alene\". Det formulerer også ansvaret kategorisk. Det trækker modaliteten for skarpt."
    }
  },
  "xhaile_coverage": {
    "A16": {
      "label": "no",
      "reason": "Svaret nævner ikke, at flere funktionsnedsættelser vurderes samlet. Det nævner heller ikke kravet om at dokumentere alle og oplyse, at der søges på flere."
    },
    "A24": {
      "label": "partial",
      "reason": "Svaret dækker, at kun den angivne funktionsnedsættelse vurderes, selv hvis der findes flere. Det mangler dog \"som udgangspunkt\" og eksemplet om omtale i lægefaglig dokumentation."
    },
    "A25": {
      "label": "partial",
      "reason": "Svaret dækker inddragelse af en anden varig funktionsnedsættelse ved fyldestgørende dokumentation og ønske, og at det er ansøgerens ansvar. Det mangler kravet om, at minimumskravene til dokumentation er opfyldt."
    }
  },
  "overall_notes": "Svaret rammer kernen i udgangspunktet og muligheden for senere tilføjelse. Det udelader samlet vurdering, dokumentationskravet, minimumskravene og forbeholdet \"som udgangspunkt\". Det angiver heller ingen kilde."
}

